from pathlib import Path
import re
errors = []
for page in Path('docs').rglob('*.md'):
    content = re.sub(r'`[^`\n]*`', '', page.read_text())
    for target in re.findall(r'\]\(([^)]+)\)', content):
        if '://' in target:
            continue
        name, _, fragment = target.partition('#')
        destination = page.parent / name if name else page
        if not destination.is_file():
            errors.append(f'{page}: missing {target}')
        elif fragment:
            headings = re.findall(r'^#+ (.+)$', destination.read_text(), re.M)
            anchors = {re.sub(r'[^\w\- ]', '', h.lower()).replace(' ', '-') for h in headings}
            if fragment not in anchors:
                errors.append(f'{page}: missing heading {target}')
if errors:
    raise SystemExit('\n'.join(errors))
print('All local documentation links and heading anchors resolve (excluding inline code examples).')
